"use client";
import { useEffect, useState } from "react";
import Icon from "./icons";
import Placeholder from "./placeholder";
import {
  CATEGORIES,
  CONTINENT_TABS,
  CONTINENT_CITIES,
  CONTINENT_COUNTRIES,
  DESTINATIONS,
  photoUrl,
} from "./data";

interface MobileDrawerProps {
  open: boolean;
  onClose: () => void;
}

export default function MobileDrawer({ open, onClose }: MobileDrawerProps) {
  const [destTab, setDestTab] = useState("trending");

  useEffect(() => {
    document.body.style.overflow = open ? "hidden" : "";
    return () => {
      document.body.style.overflow = "";
    };
  }, [open]);

  const destCities = (CONTINENT_CITIES[destTab] || [])
    .map((id) => DESTINATIONS.find((d) => d.id === id))
    .filter(Boolean) as typeof DESTINATIONS;

  return (
    <>
      <div
        onClick={onClose}
        aria-hidden="true"
        className={
          "tw-fixed tw-inset-0 tw-z-[99] tw-transition-opacity tw-duration-200 " +
          (open
            ? "tw-opacity-100 tw-pointer-events-auto"
            : "tw-opacity-0 tw-pointer-events-none")
        }
        style={{ background: "rgba(20,16,28,0.5)" }}
      />
      <aside
        aria-hidden={!open}
        className={
          "tw-fixed tw-top-0 tw-left-0 tw-bottom-0 tw-z-[100] tw-bg-white tw-flex tw-flex-col tw-transition-transform tw-duration-[250ms] tw-ease-out " +
          (open ? "tw-translate-x-0" : "-tw-translate-x-full")
        }
        style={{ width: "min(86vw, 360px)" }}
      >
        <div
          className="tw-flex tw-items-center tw-justify-between tw-px-5 tw-py-[18px]"
          style={{ borderBottom: "1px solid #ebe7f0" }}
        >
          <span
            className="tw-flex tw-items-center tw-gap-2.5 tw-font-extrabold tw-text-[19px]"
            style={{ letterSpacing: "-0.02em" }}
          >
            <img
              src="https://d2lpxiu1sq3srq.cloudfront.net/images/logo.svg"
              alt="TravelShop Booking"
              className="tw-h-[44px] tw-w-auto tw-block"
            />
          </span>
          <button
            onClick={onClose}
            aria-label="Close menu"
            className="tw-w-10 tw-h-10 tw-rounded-full tw-grid tw-place-items-center tw-bg-transparent tw-border-0 tw-cursor-pointer tw-text-[#2a2336] hover:tw-bg-[#f3f1f7]"
          >
            <Icon name="close" size={22} />
          </button>
        </div>

        <div className="tw-flex-1 tw-overflow-y-auto tw-px-3 tw-py-4">
          <details
            className="tw-px-2 tw-py-3 [&_summary::-webkit-details-marker]:tw-hidden"
            style={{ borderBottom: "1px solid #ebe7f0" }}
          >
            <summary className="tw-list-none tw-flex tw-items-center tw-justify-between tw-cursor-pointer tw-py-1.5 tw-font-semibold tw-text-[15px] tw-text-[#14101c]">
              <span>Things to do</span>
              <span className="tw-text-[20px] tw-text-[#5d556c] tw-leading-none open-marker">
                +
              </span>
            </summary>
            <div className="tw-pt-3 tw-pb-2">
              <ul className="tw-list-none tw-m-0 tw-p-0 tw-flex tw-flex-col tw-gap-0.5">
                {CATEGORIES.map((c) => (
                  <li key={c.id}>
                    <a
                      href={c.url}
                      className="tw-flex tw-items-center tw-gap-3 tw-px-2 tw-py-2.5 tw-rounded-[10px] tw-no-underline active:tw-bg-[#faf9fc]"
                    >
                      <span
                        className="tw-w-9 tw-h-9 tw-rounded-[9px] tw-overflow-hidden tw-grid tw-place-items-center tw-flex-none tw-border tw-border-solid"
                        style={{
                          background: "#faf9fc",
                          color: "#854ec9",
                          borderColor: "#ebe7f0",
                        }}
                      >
                        {c.photo ? (
                          <img
                            src={photoUrl(c.photo, 96) || ""}
                            alt=""
                            className="tw-w-full tw-h-full tw-object-cover tw-block"
                          />
                        ) : (
                          <Icon name={c.icon as never} size={18} stroke={1.8} />
                        )}
                      </span>
                      <span className="tw-flex tw-items-baseline tw-gap-2 tw-flex-1 tw-min-w-0">
                        <span className="tw-font-semibold tw-text-[14px] tw-text-[#14101c] tw-leading-[1.2]">
                          {c.name}
                        </span>
                        <span
                          className="tw-text-[12px] tw-text-[#5d556c] tw-ml-auto tw-whitespace-nowrap"
                          style={{ fontVariantNumeric: "tabular-nums" }}
                        >
                          {c.count}
                        </span>
                      </span>
                    </a>
                  </li>
                ))}
              </ul>
            </div>
          </details>

          <details
            className="tw-px-2 tw-py-3 [&_summary::-webkit-details-marker]:tw-hidden"
            style={{ borderBottom: "1px solid #ebe7f0" }}
          >
            <summary className="tw-list-none tw-flex tw-items-center tw-justify-between tw-cursor-pointer tw-py-1.5 tw-font-semibold tw-text-[15px] tw-text-[#14101c]">
              <span>Destinations</span>
              <span className="tw-text-[20px] tw-text-[#5d556c] tw-leading-none open-marker">
                +
              </span>
            </summary>
            <div className="tw-pt-3 tw-pb-2">
              <div
                className="tw-flex tw-gap-1 tw-overflow-x-auto tw--mx-3 tw-px-3 tw-pb-2"
                style={{
                  scrollbarWidth: "none",
                  borderBottom: "1px solid #ebe7f0",
                }}
              >
                {CONTINENT_TABS.map((t) => {
                  const active = destTab === t.id;
                  return (
                    <button
                      key={t.id}
                      onClick={() => setDestTab(t.id)}
                      className={
                        "tw-relative tw-inline-flex tw-items-center tw-gap-1.5 tw-flex-none tw-bg-transparent tw-border-0 tw-px-2.5 tw-py-2 tw-text-[13px] tw-font-semibold tw-cursor-pointer tw-whitespace-nowrap " +
                        (active ? "tw-text-[#854ec9]" : "tw-text-[#5d556c]")
                      }
                    >
                      <Icon name={t.icon as never} size={14} stroke={1.8} />
                      {t.label}
                      {active && (
                        <span
                          className="tw-absolute tw-left-2.5 tw-right-2.5 tw-h-[2px] tw-bg-[#854ec9]"
                          style={{ bottom: -8, borderRadius: "2px 2px 0 0" }}
                        />
                      )}
                    </button>
                  );
                })}
              </div>

              <div className="tw-text-[10.5px] tw-font-bold tw-uppercase tw-tracking-[0.08em] tw-text-[#5d556c] tw-mt-[18px] tw-mb-2.5 tw-mx-1">
                Popular countries
              </div>
              <div className="tw-flex tw-flex-wrap tw-gap-1.5">
                {(CONTINENT_COUNTRIES[destTab] || []).map((c) => (
                  <a
                    key={c.name}
                    href={c.url}
                    className="tw-inline-flex tw-items-center tw-gap-1.5 tw-px-2.5 tw-py-[7px] tw-rounded-full tw-text-[12.5px] tw-font-semibold tw-text-[#14101c] tw-bg-white tw-border tw-border-solid tw-border-[#ebe7f0] tw-no-underline tw-whitespace-nowrap active:tw-border-[#854ec9] active:tw-bg-[#faf9fc] active:tw-text-[#854ec9]"
                    style={{ lineHeight: 1 }}
                  >
                    <img
                      src={`/images/flags/${c.code}.png`}
                      srcSet={`/images/flags/${c.code}.png 2x`}
                      alt={c.name + " flag"}
                      loading="lazy"
                      className="tw-w-[18px] tw-h-[13px] tw-object-cover tw-rounded-[2px] tw-block tw-flex-none"
                    />
                    <span>{c.name}</span>
                    {/* tour count — hidden until real data is wired
                    <span className="tw-text-[11px] tw-font-semibold tw-text-[#5d556c] tw-pl-1.5 tw-relative" style={{ fontVariantNumeric: "tabular-nums" }}>
                      <span className="tw-absolute tw-left-0 tw-w-px tw-h-2.5 tw-bg-[#ebe7f0]" style={{ top: "50%", transform: "translateY(-50%)" }} aria-hidden="true" />
                      {c.tours.toLocaleString('en-US')}
                    </span>
                    */}
                  </a>
                ))}
              </div>

              <div className="tw-text-[10.5px] tw-font-bold tw-uppercase tw-tracking-[0.08em] tw-text-[#5d556c] tw-mt-[18px] tw-mb-2.5 tw-mx-1">
                Popular cities
              </div>
              <ul className="tw-list-none tw-m-0 tw-p-0 tw-flex tw-flex-col tw-gap-0.5">
                {destCities.map((d) => (
                  <li key={d.id}>
                    <a
                      href={d.url}
                      className="tw-flex tw-items-center tw-gap-3 tw-px-2 tw-py-2.5 tw-rounded-[10px] tw-no-underline active:tw-bg-[#faf9fc]"
                    >
                      <span
                        className="tw-w-9 tw-h-9 tw-rounded-[9px] tw-overflow-hidden tw-flex-none tw-border tw-border-solid"
                        style={{
                          background: "#faf9fc",
                          borderColor: "#ebe7f0",
                        }}
                      >
                        <Placeholder
                          tone={d.tone}
                          photo={d.photo}
                          alt={d.city}
                        />
                      </span>
                      <span className="tw-flex tw-items-baseline tw-gap-2 tw-flex-1 tw-min-w-0">
                        <span className="tw-font-semibold tw-text-[14px] tw-text-[#14101c] tw-leading-[1.2]">
                          {d.city}
                          <span className="tw-font-medium tw-text-[#5d556c]">
                            {" "}
                            · {d.country}
                          </span>
                        </span>
                        {/* tour count — hidden until real data is wired
                        <span className="tw-text-[12px] tw-text-[#5d556c] tw-ml-auto tw-whitespace-nowrap" style={{ fontVariantNumeric: "tabular-nums" }}>
                          {d.tours.toLocaleString('en-US')} tours
                        </span>
                        */}
                      </span>
                    </a>
                  </li>
                ))}
              </ul>
            </div>
          </details>

          <a
            href="/deals"
            className="tw-flex tw-items-center tw-justify-between tw-px-2 tw-py-[18px] tw-font-semibold tw-text-[15px] tw-text-[#14101c] tw-no-underline"
            style={{ borderBottom: "1px solid #ebe7f0" }}
          >
            <span>Deals</span>
            <span className="tw-text-[22px] tw-leading-none tw-text-[#5d556c]">
              ›
            </span>
          </a>

          <details
            className="tw-px-2 tw-py-3 [&_summary::-webkit-details-marker]:tw-hidden"
            style={{ borderBottom: "1px solid #ebe7f0" }}
          >
            <summary className="tw-list-none tw-flex tw-items-center tw-justify-between tw-cursor-pointer tw-py-1.5 tw-font-semibold tw-text-[15px] tw-text-[#14101c]">
              <span>Help &amp; support</span>
              <span className="tw-text-[20px] tw-text-[#5d556c] tw-leading-none open-marker">
                +
              </span>
            </summary>
            <div className="tw-flex tw-flex-col tw-gap-1 tw-py-2">
              <a
                href="/contact-us"
                className="tw-py-2 tw-text-[14px] tw-text-[#2a2336] tw-no-underline"
              >
                Contact us
              </a>
              <a
                href="help-center"
                className="tw-py-2 tw-text-[14px] tw-text-[#2a2336] tw-no-underline"
              >
                Help Center
              </a>
            </div>
          </details>
        </div>

        <style
          dangerouslySetInnerHTML={{
            __html: `
          details[open] > summary .open-marker::before { content: "−"; }
          details:not([open]) > summary .open-marker::before { content: "+"; }
          details > summary .open-marker { font-size: 0; }
          details > summary .open-marker::before { font-size: 20px; }
        `,
          }}
        />
      </aside>
    </>
  );
}
