"use client";
import { useEffect, useRef } from "react";
import Icon from "./icons";
import { CATEGORIES, type Destination } from "./data";
import type { SearchResult } from "./use-search";
import TourThumb from "./tour-thumb";

interface MobileSearchProps {
  open: boolean;
  onClose: () => void;
  q: string;
  setQ: (v: string) => void;
  clear: () => void;
  loading: boolean;
  popularDests: Destination[];
  results: SearchResult[] | null;
}

export default function MobileSearch({
  open,
  onClose,
  q,
  setQ,
  clear,
  loading,
  popularDests,
  results,
}: MobileSearchProps) {
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (!open) return;
    document.body.style.overflow = "hidden";
    const t = setTimeout(() => inputRef.current?.focus(), 50);
    return () => {
      document.body.style.overflow = "";
      clearTimeout(t);
    };
  }, [open]);

  if (!open) return null;

  return (
    <div
      role="dialog"
      aria-modal="true"
      className="tw-fixed tw-inset-0 tw-z-[200] tw-bg-white tw-flex tw-flex-col"
      style={{ animation: "tsb-msearch-in 0.18s ease-out" }}
    >
      <style>{`
        @keyframes tsb-msearch-in {
          from { opacity: 0; transform: translateY(8px); }
          to { opacity: 1; transform: translateY(0); }
        }
      `}</style>

      <div
        className="tw-flex tw-items-center tw-gap-2 tw-px-3 tw-py-2.5"
        style={{ borderBottom: "1px solid #ebe7f0" }}
      >
        <button
          onClick={() => {
            setQ("");
            onClose();
          }}
          aria-label="Close"
          className="tw-w-10 tw-h-10 tw-grid tw-place-items-center tw-bg-transparent tw-border-0 tw-cursor-pointer tw-text-[#14101c] tw-rounded-full active:tw-bg-[#faf9fc]"
        >
          <Icon name="arrowL" size={22} stroke={2} />
        </button>
        <div
          className="tw-flex-1 tw-flex tw-items-center tw-gap-2 tw-h-11 tw-px-3.5 tw-rounded-full"
          style={{ background: "#faf9fc", color: "#5d556c" }}
        >
          <span className="tw-text-[#854ec9] tw-flex-none">
            <Icon name="search" size={18} stroke={2} />
          </span>
          <input
            ref={inputRef}
            value={q}
            placeholder="Search tours, activities, or destinations…"
            onChange={(e) => setQ(e.target.value)}
            className="tw-flex-1 tw-border-0 tw-outline-none tw-bg-transparent tw-text-[16px] tw-text-[#14101c] tw-min-w-0 placeholder:tw-text-[#8a8398]"
          />
          {q && (
            <button
              onClick={clear}
              aria-label="Clear"
              className="tw-w-[22px] tw-h-[22px] tw-rounded-full tw-bg-[#8a8398] tw-text-white tw-border-0 tw-cursor-pointer tw-grid tw-place-items-center"
            >
              <Icon name="close" size={14} stroke={2.2} />
            </button>
          )}
        </div>
      </div>

      <div className="tw-flex-1 tw-overflow-y-auto tw-px-1 tw-pt-2 tw-pb-8">
        {!q.trim() && (
          <>
            <div className="tw-text-[11px] tw-font-bold tw-uppercase tw-tracking-[0.08em] tw-text-[#5d556c] tw-px-4 tw-pt-4 tw-pb-2">
              Popular destinations
            </div>
            <div className="tw-grid tw-grid-cols-2">
              {popularDests.map((d) => (
                <a
                  key={d.id}
                  href={d.url}
                  className="tw-flex tw-items-center tw-gap-3 tw-px-4 tw-py-3 tw-no-underline tw-text-[#14101c] active:tw-bg-[#faf9fc]"
                >
                  <span
                    className="tw-w-8 tw-h-8 tw-rounded-full tw-grid tw-place-items-center tw-text-[#854ec9] tw-flex-none"
                    style={{ background: "rgba(133, 78, 201, 0.12)" }}
                  >
                    <Icon name="pin" size={16} stroke={2} />
                  </span>
                  <span>
                    <strong className="tw-block tw-text-[14px] tw-font-semibold">
                      {d.city}
                    </strong>
                    <span className="tw-block tw-text-[12px] tw-text-[#5d556c] tw-mt-0.5">
                      {d.country}
                    </span>
                  </span>
                </a>
              ))}
            </div>
            <div className="tw-text-[11px] tw-font-bold tw-uppercase tw-tracking-[0.08em] tw-text-[#5d556c] tw-px-4 tw-pt-4 tw-pb-2">
              Browse by category
            </div>
            <div className="tw-flex tw-flex-col">
              {CATEGORIES.slice(0, 6).map((c) => (
                <a
                  key={c.id}
                  href={c.url}
                  className="tw-flex tw-items-center tw-gap-3.5 tw-px-4 tw-py-3 tw-no-underline tw-text-[#14101c] active:tw-bg-[#faf9fc]"
                >
                  <span
                    className="tw-w-9 tw-h-9 tw-rounded-full tw-grid tw-place-items-center tw-text-[#854ec9] tw-flex-none"
                    style={{ background: "rgba(133, 78, 201, 0.12)" }}
                  >
                    <Icon name={c.icon as never} size={16} stroke={2} />
                  </span>
                  <span>
                    <strong className="tw-block tw-text-[15px] tw-font-semibold">
                      {c.name}
                    </strong>
                  </span>
                </a>
              ))}
            </div>
          </>
        )}

        {loading && (
          <div className="tw-flex tw-items-center tw-justify-center tw-gap-2 tw-py-8">
            <span
              className="tw-inline-block tw-h-4 tw-w-4 tw-animate-spin tw-rounded-full tw-border-2 tw-border-solid tw-border-[#854ec9] tw-border-r-transparent"
              role="status"
              aria-label="Loading"
            />
            <span className="tw-text-[13px] tw-text-[#5d556c]">Searching...</span>
          </div>
        )}
        {!loading && results && (
          <>
            <div className="tw-text-[11px] tw-font-bold tw-uppercase tw-tracking-[0.08em] tw-text-[#5d556c] tw-px-4 tw-pt-4 tw-pb-2">
              {results.length > 0 ? `${results.length} results` : "No results"}
            </div>
            <div className="tw-flex tw-flex-col">
              {results.length === 0 && (
                <div className="tw-p-4 tw-text-[14px] tw-text-[#5d556c]">
                  No results for &ldquo;{q}&rdquo;.
                </div>
              )}
              {results.map((r) => {
                const isDest = r.type !== "tour";
                return (
                  <a
                    key={r.pageUrl}
                    href={"/" + r.pageUrl}
                    className="tw-flex tw-items-center tw-gap-3.5 tw-px-4 tw-py-3 tw-no-underline tw-text-[#14101c] active:tw-bg-[#faf9fc]"
                  >
                    <span
                      className="tw-w-[34px] tw-h-[34px] tw-rounded-[7px] tw-grid tw-place-items-center tw-flex-none tw-overflow-hidden"
                      style={{ background: "rgba(133,78,201,0.1)" }}
                    >
                      {isDest ? (
                        <svg width="14" height="14" viewBox="0 0 16 16" fill="#ef4444" xmlns="http://www.w3.org/2000/svg">
                          <path d="M8 16s6-5.686 6-10A6 6 0 0 0 2 6c0 4.314 6 10 6 10m0-7a3 3 0 1 1 0-6 3 3 0 0 1 0 6" />
                        </svg>
                      ) : (
                        <TourThumb
                          image={r.image}
                          alt={r.pageTitle}
                          className="tw-w-full tw-h-full tw-object-cover"
                          fallback={
                            <svg width="14" height="14" viewBox="0 0 16 16" fill="#0063B1" xmlns="http://www.w3.org/2000/svg">
                              <path d="M14.778.085A.5.5 0 0 1 15 .5V8a.5.5 0 0 1-.314.464L14.5 8l.186.464-.003.001-.006.003-.023.009a12 12 0 0 1-.397.15c-.264.095-.631.223-1.047.35-.816.252-1.879.523-2.71.523-.847 0-1.548-.28-2.158-.525l-.028-.01C7.68 8.71 7.14 8.5 6.5 8.5c-.7 0-1.638.23-2.437.477A20 20 0 0 0 3 9.342V15.5a.5.5 0 0 1-1 0V.5a.5.5 0 0 1 1 0v.282c.226-.079.496-.17.79-.26C4.606.272 5.67 0 6.5 0c.84 0 1.524.277 2.121.519l.043.018C9.286.788 9.828 1 10.5 1c.7 0 1.638-.23 2.437-.477a20 20 0 0 0 1.349-.476l.019-.007.004-.002h.001" />
                            </svg>
                          }
                        />
                      )}
                    </span>
                    <span className="tw-font-medium tw-text-[14px] tw-text-[#14101c]">
                      {r.pageTitle}
                    </span>
                  </a>
                );
              })}
            </div>
          </>
        )}
      </div>
    </div>
  );
}
