"use client";

import { SessionContextProvider } from "@/store/SessionContext";
import { installAuthInterceptor } from "@/lib/authSession";

// Render fazında, çocukların effect'lerindeki ilk fetch'ler ateşlenmeden önce kur.
// (window-guarded + idempotent → SSR'da no-op, sonraki render'larda no-op.)
installAuthInterceptor();

export default function SessionProviderWrapper({ children }: { children: React.ReactNode }) {
    return <SessionContextProvider>{children}</SessionContextProvider>;
}