"use client";
import { useEffect, useState } from "react";
import { setCookie } from "cookies-next";
import { loginAction } from "@/app/actions/auth";
import { primaryRole } from "@/lib/role";
import { partnerLinks } from "@/lib/partnerLinks";
import { ApiError } from "@/lib/apiClient";
import postResetPassword from "@/services/auth/resetPasswordService";
import postSignUp from "@/services/auth/signUpService";
import Icon from "./icons";

const GOOGLE_CLIENT_ID = process.env.NEXT_PUBLIC_GOOGLE_CLIENT_ID ?? "";
const FB_APP_ID = process.env.NEXT_PUBLIC_FACEBOOK_APP_ID ?? "";

interface AuthModalProps {
  open: boolean;
  onClose: () => void;
}

const inputCls =
  "tw-w-full tw-px-3.5 tw-py-3 tw-rounded-[10px] tw-text-[15px] tw-text-[#14101c] tw-outline-none tw-border tw-border-solid tw-border-[#d8d2e1] focus:tw-border-[#854ec9] placeholder:tw-text-[#8a8398] disabled:tw-opacity-50";
const labelCls = "tw-text-[13px] tw-font-semibold tw-text-[#2a2336]";
const submitCls =
  "tw-w-full tw-mt-2 tw-inline-flex tw-items-center tw-justify-center tw-gap-2 tw-px-[22px] tw-py-3.5 tw-rounded-full tw-bg-[#854ec9] hover:tw-bg-[#6a3da4] tw-text-white tw-text-[15px] tw-font-semibold tw-border-0 tw-cursor-pointer disabled:tw-opacity-60 tw-transition-colors";

export default function AuthModal({ open, onClose }: AuthModalProps) {
  const [mode, setMode] = useState<"login" | "forgot" | "register">("login");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [reg, setReg] = useState({
    firstName: "",
    lastName: "",
    phone: "",
    passwordAgain: "",
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  useEffect(() => {
    if (open) {
      document.body.style.overflow = "hidden";
    } else {
      document.body.style.overflow = "";
      setMode("login");
      setEmail("");
      setPassword("");
      setReg({ firstName: "", lastName: "", phone: "", passwordAgain: "" });
      setError("");
      setSuccess("");
    }
    return () => {
      document.body.style.overflow = "";
    };
  }, [open]);

  const switchMode = (m: typeof mode) => {
    setError("");
    setSuccess("");
    setMode(m);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");
    setSuccess("");

    if (mode === "login") {
      setLoading(true);
      try {
        // Giriş apiv3'e SUNUCUDA atılır (server action): X-App-Token sırrı server'da
        // kalır, kitle (rol) kapısı orada uygulanır. Reddedilirse token dönmez.
        const res = await loginAction(email, password);
        if (res.ok) {
          const maxAge = 60 * 60 * 24 * 365;
          // İki token: api_token (token_old) → legacy api + apiv2; Sanctum (token) → apiv3.
          setCookie("auth-token", res.token_old, { maxAge });
          setCookie("auth-token-v3", res.token, { maxAge });
          setCookie("user-email", res.user.email, { maxAge });
          setCookie("user-avatar", res.user.avatar, { maxAge });
          setCookie("user-full-name", res.user.name, { maxAge });
          setCookie("user-id", res.user.id.toString(), { maxAge });
          setCookie("user-role", primaryRole(res.user.roles), { maxAge });
          location.reload();
        } else {
          setError(
            res.reason === "operator" || res.reason === "blogger"
              ? `This is a ${res.reason === "operator" ? "tour operator" : "blogger"} account. Please sign in at the TravelShop Business panel: ${partnerLinks.login}`
              : "Invalid email or password.",
          );
          setLoading(false);
        }
      } catch {
        setError("Invalid email or password.");
        setLoading(false);
      }
    } else if (mode === "forgot") {
      setLoading(true);
      try {
        await postResetPassword({ email });
        setSuccess("Password reset email sent. Please check your inbox.");
      } catch {
        setError("Invalid email address.");
      }
      setLoading(false);
    } else {
      if (password !== reg.passwordAgain) {
        setError("Passwords do not match.");
        return;
      }
      if (password.length < 6) {
        setError("Password must be at least 6 characters.");
        return;
      }
      setLoading(true);
      try {
        // apiv3 /auth/register login ile aynı kontratı döner: { token (Sanctum),
        // token_old (api_token), user }. İki token: api_token → legacy api + apiv2,
        // Sanctum → apiv3. 422'de apiClient ApiError fırlatır.
        const res = await postSignUp({
          requestData: {
            email,
            password,
            phone: reg.phone,
            firstName: reg.firstName,
            lastName: reg.lastName,
          },
        });
        const maxAge = 60 * 60 * 24 * 365;
        setCookie("auth-token", res.token_old, { maxAge });
        setCookie("auth-token-v3", res.token, { maxAge });
        setCookie("user-email", res.user.email, { maxAge });
        setCookie("user-avatar", res.user.avatar ?? "", { maxAge });
        setCookie("user-full-name", res.user.name, { maxAge });
        setCookie("user-id", res.user.id.toString(), { maxAge });
        setCookie("user-role", primaryRole(res.user.roles), { maxAge });
        location.reload();
      } catch (err) {
        if (err instanceof ApiError && err.errors) {
          const firstKey = Object.keys(err.errors)[0];
          setError(
            firstKey ? err.errors[firstKey][0] : "Registration failed."
          );
        } else {
          setError("This email or phone is already registered.");
        }
        setLoading(false);
      }
    }
  };

  const handleSocialLogin = (provider: "google" | "facebook") => {
    const returnTo = encodeURIComponent(window.location.href);
    const base = `${window.location.origin}/auth/callback`;
    if (provider === "google") {
      const p = new URLSearchParams({
        client_id: GOOGLE_CLIENT_ID,
        redirect_uri: `${base}?p=g`,
        response_type: "code",
        scope: "openid email profile",
        state: returnTo,
        access_type: "online",
      });
      window.location.href = `https://accounts.google.com/o/oauth2/v2/auth?${p}`;
    } else {
      const p = new URLSearchParams({
        client_id: FB_APP_ID,
        redirect_uri: `${base}?p=f`,
        scope: "email,public_profile",
        state: returnTo,
      });
      window.location.href = `https://www.facebook.com/v18.0/dialog/oauth?${p}`;
    }
  };

  if (!open) return null;

  return (
    <>
      <div
        onClick={onClose}
        className="tw-fixed tw-inset-0 tw-z-[999]"
        style={{
          background: "rgba(20, 16, 28, 0.6)",
          backdropFilter: "blur(4px)",
          animation: "tsb-auth-fadein 0.2s ease",
        }}
        aria-hidden="true"
      />
      <div
        role="dialog"
        aria-modal="true"
        className="tw-fixed tw-left-1/2 tw-top-1/2 tw-w-[90%] tw-max-w-[440px] tw-bg-white tw-z-[1000] max-[520px]:tw-w-[94%] max-[520px]:tw-max-w-none"
        style={{
          transform: "translate(-50%, -50%)",
          borderRadius: 20,
          padding: "32px",
          boxShadow: "0 24px 60px rgba(20, 16, 28, 0.24)",
          animation: "tsb-auth-slidein 0.3s cubic-bezier(.5, 0, .25, 1)",
          maxHeight: "90vh",
          overflowY: "auto",
        }}
      >
        <style>{`
          @keyframes tsb-auth-fadein { from{opacity:0;} to{opacity:1;} }
          @keyframes tsb-auth-slidein {
            from { opacity: 0; transform: translate(-50%, -46%); }
            to { opacity: 1; transform: translate(-50%, -50%); }
          }
        `}</style>

        <button
          onClick={onClose}
          aria-label="Close"
          className="tw-absolute tw-top-4 tw-right-4 tw-w-9 tw-h-9 tw-rounded-full tw-grid tw-place-items-center tw-bg-[#faf9fc] tw-text-[#2a2336] tw-border-0 tw-cursor-pointer hover:tw-bg-[#ebe7f0] hover:tw-text-[#14101c] tw-transition-colors"
        >
          <Icon name="close" size={20} stroke={2.2} />
        </button>

        {/* ── LOGIN ── */}
        {mode === "login" && (
          <>
            <div className="tw-mb-6">
              <h2
                className="tw-text-[22px] tw-font-bold tw-text-[#14101c] tw-mb-2 tw-mt-0"
                style={{ letterSpacing: "-0.02em" }}
              >
                Welcome back
              </h2>
              <p className="tw-text-[14px] tw-text-[#5d556c] tw-leading-[1.5] tw-m-0">
                Sign in to your TravelShop Booking account
              </p>
            </div>

            {error && (
              <div
                className="tw-mb-4 tw-px-4 tw-py-3 tw-rounded-[10px] tw-text-[13.5px] tw-text-[#b91c1c]"
                style={{ background: "rgba(239,68,68,0.08)" }}
              >
                {error}
              </div>
            )}

            <form onSubmit={handleSubmit} className="tw-flex tw-flex-col">
              <div className="tw-flex tw-flex-col tw-gap-1.5">
                <label htmlFor="auth-email" className={labelCls}>
                  Email
                </label>
                <input
                  id="auth-email"
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="Enter your email address"
                  required
                  disabled={loading}
                  className={inputCls}
                />
              </div>

              {/* Reveals when user starts typing email */}
              <div
                style={{
                  display: "grid",
                  gridTemplateRows: email.trim() ? "1fr" : "0fr",
                  transition: "grid-template-rows 0.35s ease",
                }}
              >
                <div style={{ overflow: "hidden" }}>
                  <div
                    className="tw-flex tw-flex-col tw-gap-4 tw-pt-4"
                    style={{
                      opacity: email.trim() ? 1 : 0,
                      transition: "opacity 0.25s ease 0.1s",
                    }}
                  >
                    <div className="tw-flex tw-flex-col tw-gap-1.5">
                      <label htmlFor="auth-password" className={labelCls}>
                        Password
                      </label>
                      <input
                        id="auth-password"
                        type="password"
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        placeholder="••••••••"
                        required
                        disabled={loading}
                        className={inputCls}
                      />
                    </div>
                    <div className="tw-text-right tw--mt-2">
                      <button
                        type="button"
                        onClick={() => switchMode("forgot")}
                        className="tw-text-[13px] tw-text-[#854ec9] tw-font-semibold tw-bg-transparent tw-border-0 tw-cursor-pointer tw-p-0 hover:tw-underline"
                      >
                        Forgot password?
                      </button>
                    </div>
                    <button
                      type="submit"
                      disabled={loading}
                      className={submitCls}
                    >
                      {loading ? (
                        <>
                          <span
                            className="tw-inline-block tw-h-4 tw-w-4 tw-animate-spin tw-rounded-full tw-border-2 tw-border-solid tw-border-current tw-border-r-transparent tw-align-[-2px]"
                            role="status"
                            aria-hidden="true"
                          />{" "}
                          Signing in…
                        </>
                      ) : (
                        "Sign in"
                      )}
                    </button>
                  </div>
                </div>
              </div>
            </form>

            <div className="tw-relative tw-text-center tw-my-5">
              <span
                className="tw-absolute tw-left-0 tw-right-0 tw-h-px tw-bg-[#ebe7f0]"
                style={{ top: "50%" }}
                aria-hidden="true"
              />
              <span className="tw-relative tw-inline-block tw-bg-white tw-px-3 tw-text-[13px] tw-text-[#5d556c] tw-font-medium">
                or
              </span>
            </div>

            <div className="tw-flex tw-flex-col tw-gap-2.5 tw-mb-5">
              <button
                type="button"
                onClick={() => handleSocialLogin("google")}
                className="tw-w-full tw-flex tw-items-center tw-justify-center tw-gap-2.5 tw-p-3 tw-border tw-border-solid tw-border-[#d8d2e1] tw-bg-white tw-text-[15px] tw-font-semibold tw-text-[#14101c] tw-cursor-pointer hover:tw-border-[#14101c] hover:tw-bg-[#faf9fc] tw-rounded-[12px] tw-transition-colors"
              >
                <svg width="18" height="18" viewBox="0 0 18 18" fill="none">
                  <path
                    d="M17.64 9.2c0-.637-.057-1.251-.164-1.84H9v3.481h4.844c-.209 1.125-.843 2.078-1.796 2.717v2.258h2.908c1.702-1.567 2.684-3.875 2.684-6.615z"
                    fill="#4285F4"
                  />
                  <path
                    d="M9.003 18c2.43 0 4.467-.806 5.956-2.184L12.05 13.56c-.806.54-1.836.86-3.047.86-2.344 0-4.328-1.584-5.036-3.711H.96v2.332C2.438 15.983 5.482 18 9.003 18z"
                    fill="#34A853"
                  />
                  <path
                    d="M3.964 10.712c-.18-.54-.282-1.117-.282-1.71 0-.593.102-1.17.282-1.71V4.96H.957C.347 6.175 0 7.55 0 9.002c0 1.452.348 2.827.957 4.042l3.007-2.332z"
                    fill="#FBBC05"
                  />
                  <path
                    d="M9.003 3.58c1.321 0 2.508.454 3.44 1.345l2.582-2.58C13.464.891 11.426 0 9.003 0 5.482 0 2.438 2.017.96 4.958L3.967 7.29c.708-2.127 2.692-3.71 5.036-3.71z"
                    fill="#EA4335"
                  />
                </svg>
                Continue with Google
              </button>
              <button
                type="button"
                onClick={() => handleSocialLogin("facebook")}
                className="tw-w-full tw-flex tw-items-center tw-justify-center tw-gap-2.5 tw-p-3 tw-border tw-border-solid tw-border-[#d8d2e1] tw-bg-white tw-text-[15px] tw-font-semibold tw-text-[#14101c] tw-cursor-pointer hover:tw-border-[#14101c] hover:tw-bg-[#faf9fc] tw-rounded-[12px] tw-transition-colors"
              >
                <svg width="18" height="18" viewBox="0 0 24 24" fill="#1877F2">
                  <path d="M24 12.073C24 5.405 18.627 0 12 0S0 5.405 0 12.073C0 18.1 4.388 23.094 10.125 24v-8.437H7.078v-3.49h3.047V9.41c0-3.025 1.792-4.697 4.533-4.697 1.312 0 2.686.235 2.686.235v2.97h-1.513c-1.491 0-1.956.93-1.956 1.886v2.268h3.328l-.532 3.49h-2.796V24C19.612 23.094 24 18.1 24 12.073z" />
                </svg>
                Continue with Facebook
              </button>
            </div>

            <div className="tw-text-center tw-text-[14px] tw-text-[#5d556c]">
              Don&apos;t have an account?{" "}
              <button
                type="button"
                onClick={() => switchMode("register")}
                className="tw-text-[#854ec9] tw-font-semibold tw-bg-transparent tw-border-0 tw-cursor-pointer tw-p-0 hover:tw-underline"
              >
                Create one
              </button>
            </div>
          </>
        )}

        {/* ── FORGOT PASSWORD ── */}
        {mode === "forgot" && (
          <>
            <div className="tw-mb-6">
              <h2
                className="tw-text-[22px] tw-font-bold tw-text-[#14101c] tw-mb-2 tw-mt-0"
                style={{ letterSpacing: "-0.02em" }}
              >
                Reset your password
              </h2>
              <p className="tw-text-[14px] tw-text-[#5d556c] tw-leading-[1.5] tw-m-0">
                Enter your email and we&apos;ll send you a link to reset your
                password.
              </p>
            </div>

            {error && (
              <div
                className="tw-mb-4 tw-px-4 tw-py-3 tw-rounded-[10px] tw-text-[13.5px] tw-text-[#b91c1c]"
                style={{ background: "rgba(239,68,68,0.08)" }}
              >
                {error}
              </div>
            )}
            {success && (
              <div
                className="tw-mb-4 tw-px-4 tw-py-3 tw-rounded-[10px] tw-text-[13.5px] tw-text-[#15803d]"
                style={{ background: "rgba(22,163,74,0.08)" }}
              >
                {success}
              </div>
            )}

            <form
              onSubmit={handleSubmit}
              className="tw-flex tw-flex-col tw-gap-4"
            >
              <div className="tw-flex tw-flex-col tw-gap-1.5">
                <label htmlFor="auth-email-reset" className={labelCls}>
                  Email
                </label>
                <input
                  id="auth-email-reset"
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="Enter your email address"
                  required
                  disabled={loading || !!success}
                  className={inputCls}
                />
              </div>
              {!success && (
                <button type="submit" disabled={loading} className={submitCls}>
                  {loading ? (
                    <>
                      <span
                        className="tw-inline-block tw-h-4 tw-w-4 tw-animate-spin tw-rounded-full tw-border-2 tw-border-solid tw-border-current tw-border-r-transparent tw-align-[-2px]"
                        role="status"
                        aria-hidden="true"
                      />{" "}
                      Sending…
                    </>
                  ) : (
                    "Send reset link"
                  )}
                </button>
              )}
            </form>
            <div className="tw-mt-4 tw-text-center">
              <button
                onClick={() => switchMode("login")}
                type="button"
                className="tw-inline-flex tw-items-center tw-gap-1.5 tw-text-[14px] tw-text-[#854ec9] tw-font-semibold tw-bg-transparent tw-border-0 tw-cursor-pointer tw-p-0 hover:tw-underline"
              >
                <Icon name="arrowL" size={14} stroke={2.4} />
                Back to sign in
              </button>
            </div>
          </>
        )}

        {/* ── REGISTER ── */}
        {mode === "register" && (
          <>
            <div className="tw-mb-6">
              <h2
                className="tw-text-[22px] tw-font-bold tw-text-[#14101c] tw-mb-2 tw-mt-0"
                style={{ letterSpacing: "-0.02em" }}
              >
                Create an account
              </h2>
              <p className="tw-text-[14px] tw-text-[#5d556c] tw-leading-[1.5] tw-m-0">
                Join TravelShop Booking and start exploring the world.
              </p>
            </div>

            {error && (
              <div
                className="tw-mb-4 tw-px-4 tw-py-3 tw-rounded-[10px] tw-text-[13.5px] tw-text-[#b91c1c]"
                style={{ background: "rgba(239,68,68,0.08)" }}
              >
                {error}
              </div>
            )}
            {success && (
              <div
                className="tw-mb-4 tw-px-4 tw-py-3 tw-rounded-[10px] tw-text-[13.5px] tw-text-[#15803d]"
                style={{ background: "rgba(22,163,74,0.08)" }}
              >
                {success}
              </div>
            )}

            <form
              onSubmit={handleSubmit}
              className="tw-flex tw-flex-col tw-gap-4"
            >
              <div
                className="tw-grid tw-gap-4"
                style={{ gridTemplateColumns: "1fr 1fr" }}
              >
                <div className="tw-flex tw-flex-col tw-gap-1.5">
                  <label htmlFor="reg-first" className={labelCls}>
                    First name
                  </label>
                  <input
                    id="reg-first"
                    type="text"
                    value={reg.firstName}
                    onChange={(e) =>
                      setReg({ ...reg, firstName: e.target.value })
                    }
                    placeholder="Enter your first name"
                    required
                    disabled={loading || !!success}
                    className={inputCls}
                  />
                </div>
                <div className="tw-flex tw-flex-col tw-gap-1.5">
                  <label htmlFor="reg-last" className={labelCls}>
                    Last name
                  </label>
                  <input
                    id="reg-last"
                    type="text"
                    value={reg.lastName}
                    onChange={(e) =>
                      setReg({ ...reg, lastName: e.target.value })
                    }
                    placeholder="Enter your last name"
                    required
                    disabled={loading || !!success}
                    className={inputCls}
                  />
                </div>
              </div>
              <div className="tw-flex tw-flex-col tw-gap-1.5">
                <label htmlFor="reg-email" className={labelCls}>
                  Email
                </label>
                <input
                  id="reg-email"
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="Enter your email address"
                  required
                  disabled={loading || !!success}
                  className={inputCls}
                />
              </div>
              <div className="tw-flex tw-flex-col tw-gap-1.5">
                <label htmlFor="reg-phone" className={labelCls}>
                  Phone
                </label>
                <input
                  id="reg-phone"
                  type="tel"
                  value={reg.phone}
                  onChange={(e) => setReg({ ...reg, phone: e.target.value })}
                  placeholder="+1 234 567 8900"
                  required
                  disabled={loading || !!success}
                  className={inputCls}
                />
              </div>
              <div
                className="tw-grid tw-gap-4"
                style={{ gridTemplateColumns: "1fr 1fr" }}
              >
                <div className="tw-flex tw-flex-col tw-gap-1.5">
                  <label htmlFor="reg-password" className={labelCls}>
                    Password
                  </label>
                  <input
                    id="reg-password"
                    type="password"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    placeholder="••••••••"
                    required
                    autoComplete="new-password"
                    disabled={loading || !!success}
                    className={inputCls}
                  />
                </div>
                <div className="tw-flex tw-flex-col tw-gap-1.5">
                  <label htmlFor="reg-password2" className={labelCls}>
                    Confirm
                  </label>
                  <input
                    id="reg-password2"
                    type="password"
                    value={reg.passwordAgain}
                    onChange={(e) =>
                      setReg({ ...reg, passwordAgain: e.target.value })
                    }
                    placeholder="••••••••"
                    required
                    disabled={loading || !!success}
                    className={inputCls}
                  />
                </div>
              </div>
              {!success && (
                <button type="submit" disabled={loading} className={submitCls}>
                  {loading ? (
                    <>
                      <span
                        className="tw-inline-block tw-h-4 tw-w-4 tw-animate-spin tw-rounded-full tw-border-2 tw-border-solid tw-border-current tw-border-r-transparent tw-align-[-2px]"
                        role="status"
                        aria-hidden="true"
                      />{" "}
                      Creating account…
                    </>
                  ) : (
                    "Create account"
                  )}
                </button>
              )}
            </form>

            <div className="tw-mt-4 tw-text-center tw-text-[14px] tw-text-[#5d556c]">
              Already have an account?{" "}
              <button
                type="button"
                onClick={() => switchMode("login")}
                className="tw-text-[#854ec9] tw-font-semibold tw-bg-transparent tw-border-0 tw-cursor-pointer tw-p-0 hover:tw-underline"
              >
                Sign in
              </button>
            </div>
          </>
        )}
      </div>
    </>
  );
}
