"use client";
import { useState } from "react";
import { useDebouncedCallback } from "use-debounce";
import { DESTINATIONS, type Destination } from "./data";
import { searchBar } from "@/actions/search";

export interface SearchResult {
  pageUrl: string;
  pageTitle: string;
  type: string;
  image?: string | null;
}

export type SearchStatus = "idle" | "loading" | "success" | "notfound";

const POPULAR_IDS = ["istanbul", "paris", "rome", "barcelona", "tokyo", "dubai"];

export const popularDests = POPULAR_IDS
  .map((id) => DESTINATIONS.find((d) => d.id === id))
  .filter(Boolean) as Destination[];

async function fetchSearch(term: string): Promise<SearchResult[]> {
  const res = await searchBar(term);
  return res.data && res.data.length > 0 ? res.data : [];
}

export function useSearch() {
  const [q, setQRaw] = useState("");
  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState<SearchStatus>("idle");
  const [results, setResults] = useState<SearchResult[] | null>(null);

  const runSearch = useDebouncedCallback(async (value: string) => {
    if (!value.trim()) {
      setResults(null);
      setStatus("idle");
      setLoading(false);
      return;
    }
    setLoading(true);
    try {
      const data = await fetchSearch(value);
      setResults(data);
      setStatus(data.length > 0 ? "success" : "notfound");
    } catch {
      setResults([]);
      setStatus("notfound");
    } finally {
      setLoading(false);
    }
  }, 300);

  const setQ = (value: string) => {
    setQRaw(value);
    if (!value.trim()) {
      setResults(null);
      setStatus("idle");
      setLoading(false);
      runSearch.cancel();
    } else {
      setLoading(true);
      runSearch(value);
    }
  };

  const clear = () => {
    setQRaw("");
    setResults(null);
    setStatus("idle");
    setLoading(false);
    runSearch.cancel();
  };

  return { q, setQ, clear, loading, status, results };
}
